209	#[comemo::track]
210	impl Sink {
211	    /// Trace an introspection.
212	    pub fn introspection(&mut self, introspection: Introspection) {
213	        self.introspections.push(introspection);
214	    }
215	
216	    /// Add a delayed error.
217	    pub fn delayed_error(&mut self, error: SourceDiagnostic) {
218	        self.delayed.push(error);
219	    }
220	
221	    /// Add multiple delayed errors.
222	    pub fn delayed_errors(&mut self, errors: EcoVec<SourceDiagnostic>) {
223	        self.delayed.extend(errors);
224	    }
225	
226	    /// Add a warning.
227	    pub fn warn(&mut self, warning: SourceDiagnostic) {
228	        // Check if warning is a duplicate.
229	        let hash = typst_utils::hash128(&(&warning.span, &warning.message));
230	        if self.warnings_set.insert(hash) {
231	            self.warnings.push(warning);
232	        }
233	    }
234	
235	    /// Trace a value and optionally styles for the traced span.
236	    pub fn value(&mut self, value: Value, styles: Option<Styles>) {
237	        if self.values.len() < Self::MAX_VALUES {
238	            self.values.push((value, styles));
239	        }
240	    }
241	
242	    /// Extend from parts of another sink.
243	    fn extend(
244	        &mut self,
245	        introspections: EcoVec<Introspection>,
246	        delayed: EcoVec<SourceDiagnostic>,
247	        warnings: EcoVec<SourceDiagnostic>,
248	        values: EcoVec<(Value, Option<Styles>)>,
249	    ) {
250	        self.introspections.extend(introspections);
251	        self.delayed.extend(delayed);
252	        for warning in warnings {
253	            self.warn(warning);
254	        }
255	        if let Some(remaining) = Self::MAX_VALUES.checked_sub(self.values.len()) {
256	            self.values.extend(values.into_iter().take(remaining));
257	        }
258	    }
259	}
