42	    /// Create a new world for a single test.
43	    ///
44	    /// This is cheap because the shared base for all test runs is lazily
45	    /// initialized just once.
46	    pub fn new(source: Source, features: Option<Features>) -> Self {
47	        let base = singleton!(TestBase, TestBase::default());
48	        let library = base.lib.with_features(features);
