40	impl SystemWorld {
41	    /// Creates a new system world.
42	    pub fn new(
43	        input: Option<&Input>,
44	        world_args: &'static WorldArgs,
45	        process_args: &ProcessArgs,
46	    ) -> Result<Self, WorldCreationError> {
47	        // Set up the thread pool.
48	        if let Some(jobs) = process_args.jobs {
49	            rayon::ThreadPoolBuilder::new()
50	                .num_threads(jobs)
51	                .use_current_thread()
52	                .build_global()
53	                .ok();
54	        }
55	
56	        let library = {
57	            // Convert the input pairs to a dictionary.
58	            let inputs: Dict = world_args
59	                .inputs
60	                .iter()
61	                .map(|(k, v)| (k.as_str().into(), v.as_str().into_value()))
62	                .collect();
63	
64	            let features =
65	                process_args.features.iter().copied().map(Into::into).collect();
66	
67	            Library::builder([
68	                typst_html::FORMAT,
69	                typst_pdf::FORMAT,
70	                typst_svg::FORMAT,
71	                typst_render::FORMAT,
72	                typst_bundle::FORMAT,
73	            ])
74	            .with_inputs(inputs)
75	            .with_features(features)
76	            .build()
77	        };
78	
79	        let now = match world_args.creation_timestamp {
80	            Some(time) => Time::fixed_timestamp(time)
81	                .map_err(|_| WorldCreationError::InvalidTimestamp)?,
82	            None => Time::system(),
83	        };
84	
85	        Ok(Self {
86	            workdir: std::env::current_dir().ok(),
87	            library: LazyHash::new(library),
88	            fonts: LazyLock::new(Box::new(|| {
89	                crate::fonts::discover_fonts(&world_args.font)
90	            })),
91	            files: FileStore::new(SystemFiles::new(input, world_args)?),
92	            now,
93	        })
94	    }
